-- E149 static items: only import through an owned isolated database runner.
SET NAMES utf8mb4;

CREATE TABLE `裝備_特殊_卡片_能力`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_id` int(11) NOT NULL COMMENT '卡片道具ID',
  `card_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡片顯示名稱',
  `item_type` int(11) NULL DEFAULT 0 COMMENT '限制部位: 1武器 2防具 3飾品 6通用',
  `limit_count` int(11) NULL DEFAULT 1 COMMENT '同裝備限制張數',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註',
  `add_str` int(11) NULL DEFAULT 0,
  `add_dex` int(11) NULL DEFAULT 0,
  `add_con` int(11) NULL DEFAULT 0,
  `add_int` int(11) NULL DEFAULT 0,
  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_hpr` int(11) NULL DEFAULT 0,
  `add_mpr` int(11) NULL DEFAULT 0,
  `add_sp` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0,
  `add_hit` int(11) NULL DEFAULT 0,
  `add_dmg` int(11) NULL DEFAULT 0,
  `add_bow_hit` int(11) NULL DEFAULT 0,
  `add_bow_dmg` int(11) NULL DEFAULT 0,
  `add_magic_hit` int(11) NULL DEFAULT 0,
  `add_magic_dmg` int(11) NULL DEFAULT 0,
  `add_ac` int(11) NULL DEFAULT 0,
  `add_reduction` int(11) NULL DEFAULT 0,
  `add_melee_redux` int(11) NULL DEFAULT 0,
  `add_bow_redux` int(11) NULL DEFAULT 0,
  `add_ignore_reduction` int(11) NULL DEFAULT 0,
  `add_pvp_dmg` int(11) NULL DEFAULT 0,
  `add_pvp_redux` int(11) NULL DEFAULT 0,
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_pierce` int(11) NULL DEFAULT 0,
  `add_stun_success` int(11) NULL DEFAULT 0,
  `add_weight_reduction` int(11) NULL DEFAULT 0,
  `add_fire` int(11) NULL DEFAULT 0,
  `add_water` int(11) NULL DEFAULT 0,
  `add_wind` int(11) NULL DEFAULT 0,
  `add_earth` int(11) NULL DEFAULT 0,
  `regist_stun` int(11) NULL DEFAULT 0,
  `regist_stone` int(11) NULL DEFAULT 0,
  `regist_sleep` int(11) NULL DEFAULT 0,
  `regist_freeze` int(11) NULL DEFAULT 0,
  `regist_blind` int(11) NULL DEFAULT 0,
  `regist_sustain` int(11) NULL DEFAULT 0,
  `add_potion_recovery` int(11) NULL DEFAULT 0,
  `add_poison_resist` int(11) NULL DEFAULT 0,
  `add_exp_rate` int(11) NULL DEFAULT 0,
  `add_drop_rate` int(11) NULL DEFAULT 0,
  `add_adena_rate` int(11) NULL DEFAULT 0,
  `add_dodge` int(11) NULL DEFAULT 0,
  `add_er` int(11) NULL DEFAULT 0,
  `add_magic_dmg_redux` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 118 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;


