CREATE TABLE `裝備_armor_魔法`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_id` int(11) NOT NULL COMMENT '道具ID',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `enchant_level` int(11) NOT NULL COMMENT '強化等級(-1=不限制)',
  `proc_group` int(11) NOT NULL DEFAULT 1 COMMENT '效果群組(同道具分組管理)',
  `on_attack_chance` int(11) NULL DEFAULT 0 COMMENT '攻擊時觸發機率 (0-100)',
  `on_hurt_chance` int(11) NULL DEFAULT 0 COMMENT '受傷時觸發機率 (0-100)',
  `flat_damage` int(11) NULL DEFAULT 0 COMMENT '固定傷害',
  `rand_damage` int(11) NULL DEFAULT 0 COMMENT '隨機傷害 (0-rand_damage)',
  `heal_hp` int(11) NULL DEFAULT 0 COMMENT 'HP回復量',
  `heal_hp_rand` int(11) NOT NULL DEFAULT 0 COMMENT 'HP吸取',
  `heal_mp` int(11) NULL DEFAULT 0 COMMENT 'MP回復量',
  `heal_mp_rand` int(11) NOT NULL DEFAULT 0 COMMENT 'MP吸取',
  `heal_mode` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=吸取 1=自身恢復',
  `trigger_skill` int(11) NULL DEFAULT 0 COMMENT '觸發技能ID (0=無)',
  `skill_time_sec` int(11) NOT NULL DEFAULT 0 COMMENT 'trigger_skill 持續秒數，0=沿用 skills 表',
  `skill_target` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=預設目標 1=自身BUFF',
  `gfx_id` int(11) NULL DEFAULT 0 COMMENT '動畫ID',
  `gfx_mode` int(11) NULL DEFAULT 0 COMMENT '動畫模式 (0=目標, 1=自己, 2=雙方)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_item_id`(`item_id`) USING BTREE,
  INDEX `idx_enchant_level`(`enchant_level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '裝備觸發特效表' ROW_FORMAT = COMPACT;


