CREATE TABLE `裝備_armor_bless_指定`  (
  `item_id` int(11) NOT NULL COMMENT '道具ID (armor 表的 item_id)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品說明文字',
  `bless_id` tinyint(4) NOT NULL DEFAULT 1 COMMENT '祝福狀態 (0:祝福, 1:一般, 2:詛咒)',
  `add_str` tinyint(4) NULL DEFAULT 0 COMMENT '力量 (STR)',
  `add_dex` tinyint(4) NULL DEFAULT 0 COMMENT '敏捷 (DEX)',
  `add_con` tinyint(4) NULL DEFAULT 0 COMMENT '體質 (CON)',
  `add_int` tinyint(4) NULL DEFAULT 0 COMMENT '智力 (INT)',
  `add_wis` tinyint(4) NULL DEFAULT 0 COMMENT '精神 (WIS)',
  `add_cha` tinyint(4) NULL DEFAULT 0 COMMENT '魅力 (CHA)',
  `add_hp` smallint(6) NULL DEFAULT 0 COMMENT '體力值 (HP)',
  `add_mp` smallint(6) NULL DEFAULT 0 COMMENT '魔力值 (MP)',
  `add_hpr` tinyint(4) NULL DEFAULT 0 COMMENT '體力回復 (HP Regen)',
  `add_mpr` tinyint(4) NULL DEFAULT 0 COMMENT '魔力回復 (MP Regen)',
  `add_mr` tinyint(4) NULL DEFAULT 0 COMMENT '魔法防禦 (MR)',
  `add_sp` tinyint(4) NULL DEFAULT 0 COMMENT '魔法攻擊 (SP)',
  `add_hit` tinyint(4) NULL DEFAULT 0 COMMENT '近戰命中 (Hit Modifier)',
  `add_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '近戰傷害 (Damage Modifier)',
  `add_bow_hit` tinyint(4) NULL DEFAULT 0 COMMENT '遠攻命中 (Bow Hit)',
  `add_bow_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '遠攻傷害 (Bow Damage)',
  `add_magic_hit` tinyint(4) NULL DEFAULT 0 COMMENT '魔法命中 (Magic Hit)',
  `add_magic_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '魔法傷害 (Magic Damage Modifier)',
  `add_ac` tinyint(4) NULL DEFAULT 0 COMMENT '防禦等級 (AC) - 注意：資料庫存正數，程式會轉為負數',
  `add_melee_redux` tinyint(4) NULL DEFAULT 0 COMMENT '近戰減免 (Melee Reduction)',
  `add_bow_redux` tinyint(4) NULL DEFAULT 0 COMMENT '遠攻減免 (Bow Reduction)',
  `add_reduction` tinyint(4) NULL DEFAULT 0 COMMENT '傷害減免 (Damage Reduction)',
  `add_dodge` tinyint(4) NULL DEFAULT 0 COMMENT '閃避 (Dodge)',
  `add_er` tinyint(4) NULL DEFAULT 0 COMMENT '遠距離迴避 (Evasion Rate)',
  `add_fire` tinyint(4) NULL DEFAULT 0 COMMENT '火屬性防禦 (Fire Defense)',
  `add_water` tinyint(4) NULL DEFAULT 0 COMMENT '水屬性防禦 (Water Defense)',
  `add_wind` tinyint(4) NULL DEFAULT 0 COMMENT '風屬性防禦 (Wind Defense)',
  `add_earth` tinyint(4) NULL DEFAULT 0 COMMENT '地屬性防禦 (Earth Defense)',
  `add_pvp_dmg` tinyint(4) NULL DEFAULT 0 COMMENT 'PVP 額外傷害 (PVP Damage)',
  `add_pvp_redux` tinyint(4) NULL DEFAULT 0 COMMENT 'PVP 傷害減免 (PVP Reduction)',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `regist_freeze` tinyint(4) NULL DEFAULT 0 COMMENT '冰凍耐性 (Freeze Resistance)',
  `regist_stone` tinyint(4) NULL DEFAULT 0 COMMENT '石化耐性 (Stone Resistance)',
  `regist_sleep` tinyint(4) NULL DEFAULT 0 COMMENT '睡眠耐性 (Sleep Resistance)',
  `regist_blind` tinyint(4) NULL DEFAULT 0 COMMENT '失明耐性 (Blind Resistance)',
  `regist_sustain` tinyint(4) NULL DEFAULT 0 COMMENT '持續傷害耐性 (Sustain Resistance)',
  `regist_stun` tinyint(4) NULL DEFAULT 0 COMMENT '暈眩耐性 (Stun Resistance)',
  `add_pierce` tinyint(4) NULL DEFAULT 0 COMMENT '貫穿 (Pierce)',
  `add_stun_success` tinyint(4) NULL DEFAULT 0 COMMENT '暈眩成功率 (Stun Success)',
  `add_ignore_reduction` tinyint(4) NULL DEFAULT 0 COMMENT '無視減免 (Ignore Reduction)',
  `add_potion_recovery` tinyint(4) NULL DEFAULT 0 COMMENT '藥水恢復加成 (Potion Recovery)',
  `add_poison_resist` tinyint(4) NULL DEFAULT 0 COMMENT '毒性抗性 (Poison Resist)',
  `add_exp_rate` tinyint(4) NULL DEFAULT 0 COMMENT '經驗值加成 (%) (EXP Rate)',
  `add_drop_rate` tinyint(4) NULL DEFAULT 0 COMMENT '掉寶率加成 (%) (Drop Rate)',
  `add_adena_rate` tinyint(4) NULL DEFAULT 0 COMMENT '金幣掉落加成 (%) (Adena Rate)',
  PRIMARY KEY (`item_id`, `bless_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '防具特定ID能力表' ROW_FORMAT = COMPACT;

CREATE TABLE `裝備_armor_bless_類型`  (
  `bless_id` int(11) NOT NULL COMMENT '祝福狀態 (0=祝福, 1=一般, 2=詛咒)',
  `armor_type` int(11) NOT NULL COMMENT '防具類型 (1=頭盔, 2=盔甲, 3=T恤, 4=斗篷, 5=手套, 6=靴子, 7=盾牌, 8=項鍊, 9=戒指, 10=腰帶, 11=耳環)',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `add_str` int(11) NULL DEFAULT 0 COMMENT '力量加成',
  `add_dex` int(11) NULL DEFAULT 0 COMMENT '敏捷加成',
  `add_con` int(11) NULL DEFAULT 0 COMMENT '體質加成',
  `add_int` int(11) NULL DEFAULT 0 COMMENT '智力加成',
  `add_wis` int(11) NULL DEFAULT 0 COMMENT '精神加成',
  `add_cha` int(11) NULL DEFAULT 0 COMMENT '魅力加成',
  `add_hp` int(11) NULL DEFAULT 0 COMMENT 'HP加成',
  `add_mp` int(11) NULL DEFAULT 0 COMMENT 'MP加成',
  `add_hpr` int(11) NULL DEFAULT 0 COMMENT 'HP回復增加',
  `add_mpr` int(11) NULL DEFAULT 0 COMMENT 'MP回復增加',
  `add_mr` int(11) NULL DEFAULT 0 COMMENT '魔法防禦加成',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '負重減輕',
  `add_ac` int(11) NULL DEFAULT 0 COMMENT 'AC加成 (正值表示減少AC，提升防禦)',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_melee_redux` int(11) NULL DEFAULT 0 COMMENT '近戰傷害減免',
  `add_bow_redux` int(11) NULL DEFAULT 0 COMMENT '遠程傷害減免',
  `add_dodge` int(11) NULL DEFAULT 0 COMMENT '閃避率',
  `add_er` int(11) NULL DEFAULT 0 COMMENT '遠距離迴避',
  `def_fire` int(11) NULL DEFAULT 0 COMMENT '火屬性防禦',
  `def_water` int(11) NULL DEFAULT 0 COMMENT '水屬性防禦',
  `def_wind` int(11) NULL DEFAULT 0 COMMENT '風屬性防禦',
  `def_earth` int(11) NULL DEFAULT 0 COMMENT '地屬性防禦',
  `add_pvp_dmg` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害加成',
  `add_pvp_redux` int(11) NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `regist_freeze` int(11) NULL DEFAULT 0 COMMENT '冰凍耐性',
  `regist_stone` int(11) NULL DEFAULT 0 COMMENT '石化耐性',
  `regist_sleep` int(11) NULL DEFAULT 0 COMMENT '睡眠耐性',
  `regist_blind` int(11) NULL DEFAULT 0 COMMENT '失明耐性',
  `regist_stun` int(11) NULL DEFAULT 0 COMMENT '昏迷耐性',
  `regist_sustain` int(11) NULL DEFAULT 0 COMMENT '持續耐性',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量增加',
  `add_poison_resist` int(11) NULL DEFAULT 0 COMMENT '毒性抵抗',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗值獲取率',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶率',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣獲取率',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
  `add_hit` int(11) NOT NULL DEFAULT 0 COMMENT '近距離命中',
  `add_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '近距離傷害',
  `add_bow_hit` int(11) NOT NULL DEFAULT 0 COMMENT '遠距離命中',
  `add_bow_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '遠距離傷害',
  `add_magic_hit` int(11) NOT NULL DEFAULT 0 COMMENT '魔法命中',
  `add_magic_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '魔法傷害',
  `add_pierce` int(11) NOT NULL DEFAULT 0 COMMENT '貫穿',
  `add_stun_success` int(11) NOT NULL DEFAULT 0 COMMENT '暈眩命中',
  PRIMARY KEY (`bless_id`, `armor_type`) USING BTREE,
  INDEX `idx_bless_id`(`bless_id`) USING BTREE,
  INDEX `idx_armor_type`(`armor_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '防具祝福能力表' ROW_FORMAT = COMPACT;


