CREATE TABLE `裝備_armor_greater_類型`  (
  `tier_id` int(11) NOT NULL COMMENT '階級ID (對應 character_items.greater)',
  `armor_type` int(11) NOT NULL COMMENT '防具類型 (1=頭盔, 2=盔甲...)',
  `裝備說明` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `chance` int(11) NULL DEFAULT 0 COMMENT '獲取機率/權重',
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `add_ac` int(11) NULL DEFAULT 0 COMMENT '增加防禦 (正數=增強)',
  `add_melee_redux` int(11) NULL DEFAULT 0 COMMENT '近戰減免',
  `add_bow_redux` int(11) NULL DEFAULT 0 COMMENT '遠攻減免',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '全傷害減免',
  `add_hit` int(11) NULL DEFAULT 0,
  `add_dmg` int(11) NULL DEFAULT 0,
  `add_bow_hit` int(11) NULL DEFAULT 0,
  `add_bow_dmg` int(11) NULL DEFAULT 0,
  `add_magic_hit` int(11) NULL DEFAULT 0,
  `add_magic_dmg` int(11) NULL DEFAULT 0,
  `add_str` int(11) NULL DEFAULT 0,
  `add_dex` int(11) NULL DEFAULT 0,
  `add_con` int(11) NULL DEFAULT 0,
  `add_int` int(11) NULL DEFAULT 0,
  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_hpr` int(11) NULL DEFAULT 0,
  `add_mpr` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0,
  `add_sp` int(11) NULL DEFAULT 0,
  `add_fire` int(11) NULL DEFAULT 0,
  `add_water` int(11) NULL DEFAULT 0,
  `add_wind` int(11) NULL DEFAULT 0,
  `add_earth` int(11) NULL DEFAULT 0,
  `regist_stun` int(11) NULL DEFAULT 0 COMMENT '昏迷耐性',
  `regist_stone` int(11) NULL DEFAULT 0 COMMENT '石化耐性',
  `regist_sleep` int(11) NULL DEFAULT 0 COMMENT '睡眠耐性',
  `regist_blind` int(11) NULL DEFAULT 0 COMMENT '暗黑耐性',
  `regist_freeze` int(11) NULL DEFAULT 0 COMMENT '寒冰耐性',
  `regist_sustain` int(11) NULL DEFAULT 0 COMMENT '支撐耐性',
  `add_ignore_reduction` int(11) NULL DEFAULT 0,
  `add_dodge` int(11) NULL DEFAULT 0,
  `add_er` int(11) NULL DEFAULT 0,
  `add_potion_recovery` int(11) NULL DEFAULT 0,
  `add_poison_resist` int(11) NULL DEFAULT 0,
  `add_exp_rate` int(11) NULL DEFAULT 0,
  `add_drop_rate` int(11) NULL DEFAULT 0,
  `add_adena_rate` int(11) NULL DEFAULT 0,
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '暈眩命中 (防具也可能加)',
  `add_pierce` int(11) NOT NULL DEFAULT 0 COMMENT '貫穿',
  `add_pvp_dmg` int(11) NULL DEFAULT 0,
  `add_pvp_redux` int(11) NULL DEFAULT 0,
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`tier_id`, `armor_type`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '防具階級能力設定' ROW_FORMAT = DYNAMIC;


