CREATE TABLE `裝備_weapon_魔法`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `weapon_id` int(10) NOT NULL COMMENT '對應武器ID (item_id)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '備註 (例如: 巴風特魔杖-地裂)',
  `prob_base` int(10) NOT NULL DEFAULT 0 COMMENT '基礎發動機率 (1/1000, 10=1%)',
  `min_enchant` int(10) NOT NULL DEFAULT 0 COMMENT '發動所需最小強化值 (例如: 7代表+7以上才發動)',
  `enchant_step` int(11) NOT NULL DEFAULT 1 COMMENT '強化值階梯 (每+N)',
  `prob_enchant` int(10) NOT NULL DEFAULT 0 COMMENT '(每+N)強化增加機率 (1/1000)',
  `dmg_type` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT 0 COMMENT '傷害類型: 0=物理, 1=魔法(看INT), 2=魔法(看SP), 3=固定值',
  `dmg_fix` int(10) NOT NULL DEFAULT 0 COMMENT '固定傷害基數',
  `dmg_rnd` int(10) NOT NULL DEFAULT 0 COMMENT '隨機傷害基數 (Dice)',
  `dmg_scaling` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '能力加成倍率 (例如: INT * 2.0)',
  `dmg_attr` tinyint(1) NOT NULL DEFAULT 0 COMMENT '屬性: 0=無, 1=地, 2=火, 4=水, 8=風',
  `gfx_id` int(10) NOT NULL DEFAULT 0 COMMENT '發動特效ID (SprId)',
  `gfx_target` tinyint(1) NOT NULL DEFAULT 0 COMMENT '特效目標: 0=敵人, 1=自己 , 2=從自己>目標',
  `area_size` int(10) NOT NULL DEFAULT 0 COMMENT '範圍半徑 (0=單體)',
  `hp_drain_fix` int(10) NOT NULL DEFAULT 0 COMMENT '吸血固定值',
  `hp_drain_rnd` int(10) NOT NULL DEFAULT 0 COMMENT '吸血隨機值',
  `mp_drain_fix` int(10) NOT NULL DEFAULT 0 COMMENT '吸魔固定值',
  `mp_drain_rnd` int(10) NOT NULL DEFAULT 0 COMMENT '吸魔隨機值',
  `skill_id` int(10) NOT NULL DEFAULT 0 COMMENT '直接套用的 Skill ID',
  `skill_time_sec` int(11) NOT NULL DEFAULT 0 COMMENT '技能持續秒；0=skills.buffDuration 或 L1SkillUse 預設',
  `skill_target` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=被攻擊者 1=攻擊者自身',
  `description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品說明文字',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_weapon_id`(`weapon_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 53 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '新版武器魔法發動表' ROW_FORMAT = COMPACT;


