CREATE TABLE `裝備_weapon_bless_指定`  (
  `item_id` int(11) NOT NULL COMMENT '道具ID (weapon 表的 item_id)',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物品說明文字',
  `bless_id` tinyint(4) NOT NULL DEFAULT 1 COMMENT '祝福狀態 (0:一般, 1:祝福, 2:詛咒)',
  `add_str` tinyint(4) NULL DEFAULT 0 COMMENT '力量 (STR)',
  `add_dex` tinyint(4) NULL DEFAULT 0 COMMENT '敏捷 (DEX)',
  `add_con` tinyint(4) NULL DEFAULT 0 COMMENT '體質 (CON)',
  `add_int` tinyint(4) NULL DEFAULT 0 COMMENT '智力 (INT)',
  `add_wis` tinyint(4) NULL DEFAULT 0 COMMENT '精神 (WIS)',
  `add_cha` tinyint(4) NULL DEFAULT 0 COMMENT '魅力 (CHA)',
  `add_hp` smallint(6) NULL DEFAULT 0 COMMENT '體力值 (HP)',
  `add_mp` smallint(6) NULL DEFAULT 0 COMMENT '魔力值 (MP)',
  `add_hpr` tinyint(4) NULL DEFAULT 0 COMMENT '體力回復 (HP Regen)',
  `add_mpr` tinyint(4) NULL DEFAULT 0 COMMENT '魔力回復 (MP Regen)',
  `add_mr` tinyint(4) NULL DEFAULT 0 COMMENT '魔法防禦 (MR)',
  `add_sp` tinyint(4) NULL DEFAULT 0 COMMENT '魔法攻擊 (SP)',
  `add_hit` tinyint(4) NULL DEFAULT 0 COMMENT '近戰命中 (Hit Modifier)',
  `add_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '近戰傷害 (Damage Modifier)',
  `add_bow_hit` tinyint(4) NULL DEFAULT 0 COMMENT '遠攻命中 (Bow Hit)',
  `add_bow_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '遠攻傷害 (Bow Damage)',
  `add_magic_hit` tinyint(4) NULL DEFAULT 0 COMMENT '魔法命中 (Magic Hit)',
  `add_magic_dmg` tinyint(4) NULL DEFAULT 0 COMMENT '魔法傷害 (Magic Damage Modifier)',
  `add_dmg_small` tinyint(4) NULL DEFAULT 0 COMMENT '基礎傷害-小型 (Base Damage Small)',
  `add_dmg_large` tinyint(4) NULL DEFAULT 0 COMMENT '基礎傷害-大型 (Base Damage Large)',
  `add_pierce` tinyint(4) NULL DEFAULT 0 COMMENT '貫穿 (Pierce)',
  `add_stun_success` tinyint(4) NULL DEFAULT 0 COMMENT '暈眩成功率 (Stun Success)',
  `add_ignore_reduction` tinyint(4) NULL DEFAULT 0 COMMENT '無視減免 (Ignore Reduction)',
  `add_reduction` tinyint(4) NULL DEFAULT 0 COMMENT '傷害減免 (Damage Reduction)',
  `add_dodge` tinyint(4) NULL DEFAULT 0 COMMENT '閃避 (Dodge)',
  `add_er` tinyint(4) NULL DEFAULT 0 COMMENT '遠距離迴避 (Evasion Rate)',
  `add_fire` tinyint(4) NULL DEFAULT 0 COMMENT '火屬性防禦 (Fire Defense)',
  `add_water` tinyint(4) NULL DEFAULT 0 COMMENT '水屬性防禦 (Water Defense)',
  `add_wind` tinyint(4) NULL DEFAULT 0 COMMENT '風屬性防禦 (Wind Defense)',
  `add_earth` tinyint(4) NULL DEFAULT 0 COMMENT '地屬性防禦 (Earth Defense)',
  `add_pvp_dmg` tinyint(4) NULL DEFAULT 0 COMMENT 'PVP 額外傷害 (PVP Damage)',
  `add_pvp_redux` tinyint(4) NULL DEFAULT 0 COMMENT 'PVP 傷害減免 (PVP Reduction)',
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_potion_recovery` tinyint(4) NULL DEFAULT 0 COMMENT '藥水恢復加成 (Potion Recovery)',
  `add_poison_resist` tinyint(4) NULL DEFAULT 0 COMMENT '毒性抗性 (Poison Resist)',
  `add_exp_rate` tinyint(4) NULL DEFAULT 0 COMMENT '經驗值加成 (%) (EXP Rate)',
  `add_drop_rate` tinyint(4) NULL DEFAULT 0 COMMENT '掉寶率加成 (%) (Drop Rate)',
  `add_adena_rate` tinyint(4) NULL DEFAULT 0 COMMENT '金幣掉落加成 (%) (Adena Rate)',
  PRIMARY KEY (`item_id`, `bless_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '武器特定ID能力表' ROW_FORMAT = COMPACT;

