CREATE TABLE `裝備_weapon_greater_類型`  (
  `tier_id` int(11) NOT NULL COMMENT '階級ID (對應 character_items.greater)',
  `weapon_type` int(11) NOT NULL COMMENT '武器類型 (1=劍, 2=匕首...)',
  `裝備說明` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `chance` int(11) NULL DEFAULT 0 COMMENT '獲取機率/權重',
  `note` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '說明',
  `add_dmg_small` int(11) NULL DEFAULT 0 COMMENT '增加基礎小怪傷害',
  `add_dmg_large` int(11) NULL DEFAULT 0 COMMENT '增加基礎大怪傷害',
  `add_hit` int(11) NULL DEFAULT 0 COMMENT '近戰命中',
  `add_dmg` int(11) NULL DEFAULT 0 COMMENT '近戰傷害',
  `add_bow_hit` int(11) NULL DEFAULT 0 COMMENT '遠攻命中',
  `add_bow_dmg` int(11) NULL DEFAULT 0 COMMENT '遠攻傷害',
  `add_magic_hit` int(11) NULL DEFAULT 0 COMMENT '魔法命中',
  `add_magic_dmg` int(11) NULL DEFAULT 0 COMMENT '魔法傷害加成',
  `add_str` int(11) NULL DEFAULT 0,
  `add_dex` int(11) NULL DEFAULT 0,
  `add_con` int(11) NULL DEFAULT 0,
  `add_int` int(11) NULL DEFAULT 0,
  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_hpr` int(11) NULL DEFAULT 0,
  `add_mpr` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0 COMMENT '抗魔',
  `add_sp` int(11) NULL DEFAULT 0 COMMENT '魔攻',
  `add_reduction` int(11) NULL DEFAULT 0 COMMENT '傷害減免',
  `add_ignore_reduction` int(11) NULL DEFAULT 0 COMMENT '無視減免',
  `add_fire` int(11) NULL DEFAULT 0,
  `add_water` int(11) NULL DEFAULT 0,
  `add_wind` int(11) NULL DEFAULT 0,
  `add_earth` int(11) NULL DEFAULT 0,
  `add_pvp_dmg` int(11) NULL DEFAULT 0,
  `add_pvp_redux` int(11) NULL DEFAULT 0,
  `add_boss_dmg` int(11) NULL DEFAULT 0,
  `add_boss_redux` int(11) NULL DEFAULT 0,
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '暈眩命中率',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復量%',
  `add_exp_rate` int(11) NULL DEFAULT 0 COMMENT '經驗加成%',
  `add_drop_rate` int(11) NULL DEFAULT 0 COMMENT '掉寶加成%',
  `add_adena_rate` int(11) NULL DEFAULT 0 COMMENT '金幣加成%',
  `add_pierce` int(11) NULL DEFAULT 0 COMMENT '貫穿 (ItemAbility.PIERCE)',
  PRIMARY KEY (`tier_id`, `weapon_type`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '武器階級能力設定' ROW_FORMAT = DYNAMIC;


